    @Test void cliffMovementCannotWalkThroughATallWall(){
        for(int x=-2;x<=2;x++)for(int y=64;y<=68;y++)obstacles.add(x+","+y+",1");skills.cast(player,talent(ChickenSkill.SUPPLY),1);playerAt.set(new Location(world,0,64,4));ticks(50);for(var bird:birds){assertTrue(bird.getLocation().getZ()<1);assertEquals(64,bird.getLocation().getY(),.08);}
    }
    @Test void helpersStopBeforeUnloadedChunksRatherThanLoadingOrCrossingThem(){
        playerAt.set(new Location(world,14,64,0,-90,0));when(world.isChunkLoaded(anyInt(),anyInt())).thenAnswer(i->(int)i.getArgument(0)==0);skills.cast(player,talent(ChickenSkill.SUPPLY),1);playerAt.set(new Location(world,18,64,0,-90,0));ticks(50);assertEquals(2,birds.size());for(var bird:birds)assertTrue(bird.getLocation().getX()<15.81);verify(world,never()).getChunkAt(anyInt(),anyInt());
    }

